package com.bank.qa.design;

import java.math.BigDecimal;

// Valid transfer amount: 1 .. 100000 inclusive.
class TransferValidator {
    static final BigDecimal MIN = new BigDecimal("1");
    static final BigDecimal MAX = new BigDecimal("100000");
    boolean isValid(BigDecimal amount) {
        return amount != null
            && amount.compareTo(MIN) >= 0
            && amount.compareTo(MAX) <= 0;
    }
}
