package com.bank.qa.design;

import java.util.*;

// Lifecycle: APPLIED → APPROVED → DISBURSED → CLOSED (+ REJECTED).
class LoanStateMachine {
    enum S { APPLIED, APPROVED, DISBURSED, CLOSED, REJECTED }
    private static final Map<S, Set<S>> LEGAL = new EnumMap<>(S.class);
    static {
        LEGAL.put(S.APPLIED, EnumSet.of(S.APPROVED, S.REJECTED));
        LEGAL.put(S.APPROVED, EnumSet.of(S.DISBURSED));
        LEGAL.put(S.DISBURSED, EnumSet.of(S.CLOSED));
        LEGAL.put(S.CLOSED, EnumSet.noneOf(S.class));
        LEGAL.put(S.REJECTED, EnumSet.noneOf(S.class));
    }
    boolean canTransition(S from, S to) {
        return LEGAL.getOrDefault(from, EnumSet.noneOf(S.class)).contains(to);
    }
}
