package com.bank.qa.design;

import java.math.BigDecimal;
import java.util.logging.*;

public class TestDesignDemo {
    private static final Logger log = Logger.getLogger(TestDesignDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new DesignLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        TransferValidator tv = new TransferValidator();

        // EQUIVALENCE PARTITIONING: one representative per class
        log.info("=== Equivalence partitioning (amount 1..100000) ===");
        checkAmount(tv, new BigDecimal("-50"), false);   // below/invalid class
        checkAmount(tv, new BigDecimal("50000"), true);  // valid class
        checkAmount(tv, new BigDecimal("200000"), false);// above class

        // BOUNDARY VALUE ANALYSIS: edges where bugs cluster
        log.info("=== Boundary value analysis ===");
        checkAmount(tv, new BigDecimal("0"), false);
        checkAmount(tv, new BigDecimal("1"), true);
        checkAmount(tv, new BigDecimal("100000"), true);
        checkAmount(tv, new BigDecimal("100001"), false);

        // DECISION TABLE: all 8 combinations of 3 conditions
        log.info("=== Decision table (income, credit, age -> approve) ===");
        LoanDecision ld = new LoanDecision();
        for (int i = 0; i < 8; i++) {
            boolean inc = (i & 4) != 0, cre = (i & 2) != 0, age = (i & 1) != 0;
            boolean expect = inc && cre && age;
            boolean actual = ld.approve(inc, cre, age);
            log.info("income=" + inc + " credit=" + cre + " age=" + age
                + " -> approve=" + actual + (actual == expect ? " PASS" : " FAIL"));
        }

        // STATE TRANSITION: legal + illegal
        log.info("=== State transition (loan lifecycle) ===");
        LoanStateMachine sm = new LoanStateMachine();
        log.info("APPLIED->APPROVED legal=" + sm.canTransition(LoanStateMachine.S.APPLIED, LoanStateMachine.S.APPROVED));
        log.info("APPROVED->DISBURSED legal=" + sm.canTransition(LoanStateMachine.S.APPROVED, LoanStateMachine.S.DISBURSED));
        log.info("APPLIED->DISBURSED illegal rejected=" + !sm.canTransition(LoanStateMachine.S.APPLIED, LoanStateMachine.S.DISBURSED));

        // PAIRWISE note: 3 params x 3 values = 27 full, ~9 pairwise
        log.info("=== Pairwise: 3 params x 3 values = 27 full combos, ~9 cover all pairs ===");
    }

    private static void checkAmount(TransferValidator tv, BigDecimal amt, boolean expect) {
        boolean actual = tv.isValid(amt);
        log.info("amount=" + amt + " valid=" + actual + (actual == expect ? " PASS" : " FAIL"));
    }
}

